func ptDigestOf(k int32, want []byte) int32 {
	// -1 when the SHA-256 of image k equals line k of the committed file.
	var ws *port.Cells = port.NewCells()
	var out *port.Buf = port.NewBuf()
	var z *port.Buf = port.NewBuf()
	var raw *port.Buf = port.NewBuf()
	var row *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var pal *port.Cells = port.NewCells()
	var dig *port.Cells = port.NewCells()
	var i int32 = 0
	var at int32 = 0
	pngprobe.PpBuild(k, ws, out, z, raw, row, st, pal)
	port.CryptoSha256(port.BufBlob(out), 0, port.BufLen(out), dig)
	if port.CellsLen(dig) != 32 {
		return -3
	}
	at = k * 65
	for i < 32 {
		if port.CellsAt(dig, i) != ((16 * ptHexval(port.BlobU8(want, at+(2*i)))) + ptHexval(port.BlobU8(want, (at+(2*i))+1))) {
			return i
		}
		i += 1
	}
	return -1
}

