func TestTheChunksAreTheSpecifiedOnesAndNoOthers(emonT *testing.T) {
	// pt-read refuses any chunk but IHDR, PLTE, tRNS, pHYs, IDAT, IEND, in
	// order, so image 5 (palette, tRNS) and image 8 (pHYs) having read clean
	// is the statement; here the header's own numbers.
	var ws *port.Cells = port.NewCells()
	var out *port.Buf = port.NewBuf()
	var z *port.Buf = port.NewBuf()
	var raw *port.Buf = port.NewBuf()
	var row *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var pal *port.Cells = port.NewCells()
	var info *port.Cells = port.NewCells()
	var idat *port.Buf = port.NewBuf()
	var i int32 = 0
	for i < 16 {
		port.CellsPush(info, 0)
		i += 1
	}
	pngprobe.PpBuild(8, ws, out, z, raw, row, st, pal)
	port.AssertEq(emonT, ptRead(port.BufBlob(out), info, idat), 0, "well formed")
	port.AssertEq(emonT, port.CellsAt(info, iPpm), 11811, "300 dpi is 11811 pixels per metre")
	port.AssertEq(emonT, port.CellsAt(info, iNpal), 0, "no palette")
	port.AssertEq(emonT, port.BufAt(out, 0), 137, "signature")
	port.AssertEq(emonT, port.BufAt(out, 1), 80, "P")
	port.AssertEq(emonT, port.BufAt(out, 12), 73, "IHDR follows at 12: I")
	port.AssertEq(emonT, port.BufAt(out, port.BufLen(out)-8), 73, "IEND is the last chunk: I")
	port.AssertEq(emonT, port.BufAt(out, port.BufLen(out)-7), 69, "E")
	port.AssertEq(emonT, port.BufAt(out, port.BufLen(out)-6), 78, "N")
	port.AssertEq(emonT, port.BufAt(out, port.BufLen(out)-5), 68, "D")
}

func TestACorruptedFileIsRefusedByTheReader(emonT *testing.T) {
	// The reader is only evidence if it can say no: a flipped bit in the
	// IHDR or in the pixel data fails a CRC.
	var ws *port.Cells = port.NewCells()
	var out *port.Buf = port.NewBuf()
	var z *port.Buf = port.NewBuf()
	var raw *port.Buf = port.NewBuf()
	var row *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var pal *port.Cells = port.NewCells()
	var info *port.Cells = port.NewCells()
	var idat *port.Buf = port.NewBuf()
	var v int32 = 0
	var i int32 = 0
	for i < 16 {
		port.CellsPush(info, 0)
		i += 1
	}
	pngprobe.PpBuild(2, ws, out, z, raw, row, st, pal)
	port.AssertEq(emonT, ptRead(port.BufBlob(out), info, idat), 0, "well formed before")
	v = port.BufAt(out, 20)
	port.BufSet(out, 20, v^1)
	port.AssertEq(emonT, ptRead(port.BufBlob(out), info, idat), 2, "IHDR CRC fails")
	port.BufSet(out, 20, v)
	v = port.BufAt(out, 60)
	port.BufSet(out, 60, v^4)
	port.AssertEq(emonT, ptRead(port.BufBlob(out), info, idat), 2, "IDAT CRC fails")
	port.BufSet(out, 60, v)
	port.AssertEq(emonT, ptRead(port.BufBlob(out), info, idat), 0, "well formed again")
}

func ptRandomRgb(w int32, h int32, ws *port.Cells, out *port.Buf, z *port.Buf, raw *port.Buf, row *port.Cells, st *port.Cells, pal *port.Cells) int32 {
	// An incompressible RGB image: its IDATs must be several, each 65,536
	// bytes but the last.
	var y int32 = 0
	var i int32 = 0
	var v int32 = 0
	splitmix.SmSeed(st, 77)
	png.PngBegin(ws, out, z, w, h, 2, 8, 0, pal, 0, 0)
	for y < h {
		port.CellsDrop(row, 0)
		i = 0
		for i < (w * 3) {
			v = splitmix.SmBelow(st, 256)
			port.CellsPush(row, v)
			port.BufPush(raw, v)
			i += 1
		}
		png.PngRow(ws, out, z, row, 0)
		y += 1
	}
	png.PngEnd(ws, out, z)
	return 0
}

