func TestTheFilterIsTheOneWithTheSmallestSumTiesToTheLower(emonT *testing.T) {
	// A gray 64x8 image of identical rows, each a ramp of step 3. Row 0: `none`
	// sums 3*(0+..+63), `sub` is 3 a byte, `paeth` of a row with nothing above
	// is `sub` again, so `sub` wins the tie on being lower. Rows 1..7: `up` is
	// all zeros, and so is `paeth`; `up` wins. So filters: 1 once, 2 seven times.
	var ws *port.Cells = port.NewCells()
	var out *port.Buf = port.NewBuf()
	var z *port.Buf = port.NewBuf()
	var row *port.Cells = port.NewCells()
	var pal *port.Cells = port.NewCells()
	var info *port.Cells = port.NewCells()
	var dec *port.Cells = port.NewCells()
	var ist *port.Cells = port.NewCells()
	var idat *port.Buf = port.NewBuf()
	var y int32 = 0
	var i int32 = 0
	for i < 16 {
		port.CellsPush(info, 0)
		i += 1
	}
	png.PngBegin(ws, out, z, 64, 8, 0, 8, 0, pal, 0, 0)
	for y < 8 {
		port.CellsDrop(row, 0)
		i = 0
		for i < 64 {
			port.CellsPush(row, i*3)
			i += 1
		}
		png.PngRow(ws, out, z, row, 0)
		y += 1
	}
	png.PngEnd(ws, out, z)
	port.AssertEq(emonT, ptRead(port.BufBlob(out), info, idat), 0, "well formed")
	port.AssertEq(emonT, ptDecode(idat, info, dec, ist), 0, "inflates")
	port.AssertEq(emonT, port.CellsAt(info, iF0+0), 0, "no row with none")
	port.AssertEq(emonT, port.CellsAt(info, iF0+1), 1, "one row with sub")
	port.AssertEq(emonT, port.CellsAt(info, iF0+2), 7, "seven rows with up")
	port.AssertEq(emonT, port.CellsAt(info, iF0+3), 0, "none with average")
	port.AssertEq(emonT, port.CellsAt(info, iF0+4), 0, "none with paeth")
}

